// ====================================================
// 1. 取得資料與條件
// ====================================================
const inputItem = $json;
const liveStreamID = inputItem.liveStreamID || "N/A";
const type = inputItem.type || "N/A";
const originalConditions = inputItem.conditions || [];
const logs = inputItem.log || [];
let allFilteredLogs = [];

// ====================================================
// 🔧 輔助函數
// ====================================================
function isNumericValue(value) {
	return value !== null && value !== undefined && value !== '' && !isNaN(parseFloat(value));
}

function executeCheck(rowData, condition) {
	let met = false;
	let actualValue = null;
	let timestamp = rowData.ClientTimeUTCp8 || rowData.UTCp8;
	let isNA = false;

	try {
		const rawValue = rowData[condition.field];

		if (rawValue === null || rawValue === undefined || rawValue === '') {
			isNA = true;
		} else {
			const rawIsNumeric = isNumericValue(rawValue);
			const conditionIsNumeric = isNumericValue(condition.value);

			// 數值比較：包含 > < == !=
			if (rawIsNumeric && conditionIsNumeric) {
				actualValue = parseFloat(rawValue);
				const targetNum = parseFloat(condition.value);

				switch (condition.operator) {
					case '<':
						met = actualValue < targetNum;
						break;
					case '>':
						met = actualValue > targetNum;
						break;
					case '==':
						met = actualValue === targetNum;
						break;
					case '!=':
						met = actualValue !== targetNum;
						break;
					default:
						met = false;
				}
			} else {
				// 字串比較：忽略大小寫
				actualValue = rawValue;
				const compareValue = String(rawValue).trim().toLowerCase();
				const targetValue = String(condition.value).trim().toLowerCase();

				switch (condition.operator) {
					case '==':
						met = compareValue === targetValue;
						break;
					case '!=':
						met = compareValue !== targetValue;
						break;
					default:
						met = false;
				}
			}
		}

		// 若欄位不存在且 ignoreNA === false，視為命中
		if (isNA && condition.ignoreNA === false) {
			met = true;
		}
	} catch (e) {
		// 保持 met = false
	}

	return { met, actualValue, timestamp, isNA };
}

// ====================================================
// 🔧 主邏輯 (OR 邏輯：抓第一個符合條件)
// ====================================================
if (Array.isArray(originalConditions) && Array.isArray(logs)) {
	logs.forEach((rowData, index) => {
		const matchedCondition = originalConditions.find(condition => {
			return executeCheck(rowData, condition).met;
		});

		if (matchedCondition) {
			const { actualValue, timestamp, isNA } = executeCheck(rowData, matchedCondition);

			let snippetObj = {};
			snippetObj[matchedCondition.field] = isNA ? 'N/A' : actualValue;

			if (matchedCondition.outputs) {
				matchedCondition.outputs.forEach(outField => {
					snippetObj[outField] =
						rowData[outField] === undefined || rowData[outField] === null
							? 'N/A'
							: rowData[outField];
				});
			}

			allFilteredLogs.push({
				conditionID: matchedCondition.id,
				description: matchedCondition.description,
				lineNumber: index + 1,
				timestamp: timestamp || 'N/A',
				dataSnippet: snippetObj
			});
		}
	});
}

// ====================================================
// 排序 (由舊到新)
// ====================================================
allFilteredLogs.sort((a, b) => {
	if (a.timestamp === 'N/A') return 1;
	if (b.timestamp === 'N/A') return -1;
	return new Date(a.timestamp) - new Date(b.timestamp);
});

return {
	liveStreamID,
	type,
	conditions: originalConditions,
	filterLogs: allFilteredLogs
};

// ====================================================
// 1. 取得資料與條件
// ====================================================
const inputItem = $json;
const liveStreamID = inputItem.liveStreamID || "N/A";
const type = inputItem.type || "N/A";
const originalConditions = inputItem.conditions || [];
const logs = inputItem.log || [];
let allFilteredLogs = [];

// ====================================================
// 🔧 輔助函數：執行檢查邏輯 (維持不變)
// ====================================================
function executeCheck(rowData, condition) {
    let met = false;
    let actualValue = null;
    let timestamp = rowData.ClientTimeUTCp8 || rowData.UTCp8; 
    let isNA = false;
    let isStringCheck = false;

    try {
        const rawValue = rowData[condition.field];
        if (rawValue === null || rawValue === undefined) {
            isNA = true;
        } else if (condition.operator === '==' || condition.operator === '!=') {
            isStringCheck = true;
            actualValue = rawValue;
        } else {
            actualValue = parseFloat(rawValue);
            if (isNaN(actualValue)) isNA = true;
        }

        if (!isNA) {
            if (isStringCheck) {
                const targetValue = String(condition.value);
                const compareValue = String(actualValue);
                met = (condition.operator === '==') ? (compareValue === targetValue) : (compareValue !== targetValue);
            } else {
                const targetNum = parseFloat(condition.value);
                switch (condition.operator) {
                    case '<': met = actualValue < targetNum; break;
                    case '>': met = actualValue > targetNum; break;
                    case '==': met = actualValue === targetNum; break;
                    case '!=': met = actualValue !== targetNum; break;
                    default: met = false;
                }
            }
        } else if (condition.ignoreNA === false) {
            met = true; 
        }
    } catch (e) {}

    return { met, actualValue, timestamp, isNA };
}

// ====================================================
// 🔧 主邏輯 (AND 邏輯：使用 .every())
// ====================================================
if (Array.isArray(originalConditions) && Array.isArray(logs)) {
    logs.forEach((rowData, index) => {
        // 必須「每一項」條件都回傳 true (即：不等於 Normal Ping 且 不等於 Normal CDN...)
        const allConditionsMet = originalConditions.every(condition => {
            return executeCheck(rowData, condition).met;
        });

        if (allConditionsMet) {
            let snippetObj = {};
            let firstTimestamp = 'N/A';

            // 收集所有相關欄位資訊
            originalConditions.forEach(condition => {
                const { actualValue, timestamp, isNA } = executeCheck(rowData, condition);
                snippetObj[condition.field] = isNA ? 'N/A' : actualValue;
                if (firstTimestamp === 'N/A') firstTimestamp = timestamp;

                if (condition.outputs) {
                    condition.outputs.forEach(outField => {
                        snippetObj[outField] = (rowData[outField] === undefined) ? 'N/A' : rowData[outField];
                    });
                }
            });

            allFilteredLogs.push({
                conditionID: "COMBINED_CHECK",
                description: "Matched all exclusion criteria",
                lineNumber: index + 1,
                timestamp: firstTimestamp,
                dataSnippet: snippetObj
            });
        }
    });
}

// 排序 (由舊到新)
allFilteredLogs.sort((a, b) => {
    if (a.timestamp === 'N/A') return 1;
    if (b.timestamp === 'N/A') return -1;
    return new Date(a.timestamp) - new Date(b.timestamp);
});

return {
    liveStreamID,
    type,
    conditions: originalConditions,
    filterLogs: allFilteredLogs
};

// 1. 取得所有輸入的項目 (例如你提到的 6 個 items)
const allItems = $input.all();

// 2. 過濾無效項目並進行群組化
const grouped = allItems.reduce((acc, item) => {
  const data = item.json;

  // 過濾掉沒有 liveStreamID 或內容為空的項目
  if (data && data.liveStreamID && Object.keys(data).length > 0) {
    const sID = data.liveStreamID;

    // 如果這個 liveStreamID 還沒在累加器中，建立一個新的群組
    if (!acc[sID]) {
      acc[sID] = {
        liveStreamID: sID,
        // 你可以根據需求決定要保留哪些原始資料
        // 這裡將同一 liveStreamID 的所有內容放入一個名為 logs 的陣列中
        details: [], 
        count: 0
      };
    }

    // 將當前 item 的資料塞入該群組的陣列中
    acc[sID].details.push(data);
    acc[sID].count++;
  }

  return acc;
}, {});

// 3. 將物件轉回 n8n 預期的陣列格式 (每個 unique liveStreamID 會變成一個新的 Item)
return Object.values(grouped);

